def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != bg]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]

    def spans(n, separators):
        out, start = [], 0
        for x in separators:
            if start < x:
                out.append((start, x))
            start = x + 1
        if start < n:
            out.append((start, n))
        return out

    rs, cs = spans(h, sep_rows), spans(w, sep_cols)
    tiles = [(r0, r1, c0, c1) for r0, r1 in rs for c0, c1 in cs]
    source = None
    for r0, r1, c0, c1 in tiles:
        if any(grid[r][c] != bg for r in range(r0, r1) for c in range(c0, c1)):
            source = (r0, r1, c0, c1)
            break

    out = [row[:] for row in grid]
    if source is None:
        return out
    r0, r1, c0, c1 = source
    pattern = [row[c0:c1] for row in grid[r0:r1]]
    for a, b, x, y in tiles:
        if (b - a, y - x) == (r1 - r0, c1 - c0):
            for i in range(b - a):
                for j in range(y - x):
                    out[a + i][x + j] = pattern[i][j]
    return out
